import { getKey, sha3_256Hex } from '../crypto/native.js';

/**
 * crypto://keys/{key_id}?format=base64|pem
 *
 * Returns the public half of a key generated by quantum_key_exchange or
 * quantum_sign in this server process. Unknown key ids are an error.
 */
export function getCryptoKeyResource(uri: string): any {
  const match = uri.match(/crypto:\/\/keys\/([^?]+)/);
  if (!match) {
    throw new Error(`Invalid crypto key URI: ${uri}`);
  }

  const key_id = decodeURIComponent(match[1]);
  const url = new URL(uri.replace('crypto://', 'http://'));
  const format = url.searchParams.get('format') || 'base64';

  const key = getKey(key_id);
  if (!key) {
    throw new Error(`Unknown key_id: ${key_id}`);
  }

  const b64 = key.publicKey.toString('base64');
  const label = key.kind === 'ml-kem' ? 'ML-KEM-768 PUBLIC KEY' : 'ML-DSA-65 PUBLIC KEY';
  const data =
    format === 'pem'
      ? `-----BEGIN ${label}-----\n${(b64.match(/.{1,64}/g) || []).join('\n')}\n-----END ${label}-----`
      : b64;

  return {
    uri,
    mimeType: 'application/json',
    text: JSON.stringify(
      {
        key: {
          key_id,
          algorithm: key.algorithm,
          key_type: 'public',
          created_at: key.created_at,
          status: 'active',
        },
        public_key: {
          format: format === 'pem' ? 'pem' : 'base64',
          data,
          fingerprint: sha3_256Hex(key.publicKey),
          size_bytes: key.publicKey.length,
        },
        quantum_resistance: {
          algorithm_family: key.kind,
          security_level: 3,
          nist_approved: true,
        },
        usage: {
          purpose: [key.kind === 'ml-kem' ? 'key-encapsulation' : 'signing'],
        },
      },
      null,
      2
    ),
  };
}

